/bin/bash -lc "python3 - <<'PY'
import json,collections,re
qs=[json.loads(l) for l in open('questions.jsonl')]
targets={x for q in qs for x in re.findall(r'R5-\\d+',q['question'])}
for f in ['records/phase-1/tdocs.jsonld','records/phase-2/decision_dispositions.jsonld','records/phase-1/meetings.jsonld','records/phase-1/releases.jsonld']:
 data=json.load(open(f))['@graph']
 print('\\nFILE',f)
 if f.endswith('tdocs.jsonld'):
  for d in data:
   if d['tdoc:tdocNumber'] in ['R5-247478','R5-252659','R5-260473','R5-196161','R5-220776','R5-198404']:
    print(json.dumps(d,ensure_ascii=False))
  for k in ['targetRelease','revisedTo','isRevisionOf','tdoc:tsgCRPack','tdoc:type']:
   vals=[d[k] for d in data if k in d]
   print(k,'types',collections.Counter(type(v).__name__ for v in vals),'examples',str(vals[:6]))
 elif 'decision_dispositions' in f:
  print('evidence',collections.Counter(d['evidenceStatus'] for d in data))
  print('scope',collections.Counter(json.loads(d['assessmentMethod']).get('scope') for d in data))
  print('codes',collections.Counter(d['dispositionCode'] for d in data))
  for d in data:
   if d['targetTdocNumber'] in ['R5-220776','R5-247478','R5-198404']:
    print(json.dumps(d,ensure_ascii=False))
 elif 'meetings' in f:
  for d in data: print(json.dumps(d,ensure_ascii=False))
 else:
  for d in data[:2]: print(json.dumps(d,ensure_ascii=False))
 del data
PY"

