/bin/bash -lc "python3 - <<'PY'
import json,collections
ms={d['@id']:d for d in json.load(open('records/phase-1/meetings.jsonld'))['@graph']}
rs=json.load(open('records/phase-2/resolutions_document_dispositions.jsonld'))['@graph']
print('missing meeting ids',collections.Counter(d['madeAt'] for d in rs if d['madeAt'] not in ms))
for n in ['R5-211918','R5-191564','R5-241443','R5-210198']:
 for d in rs:
  if d['aboutTdoc']=='tdoc:'+n:print(n,d['madeAt'],d['content'][:1200])
